mapper.insert:
INSERT INTO analysis_runs (
    user_id, period_start, period_end, analysis_version, run_status
) VALUES (
    #{userId}, #{periodStart}, #{periodEnd}, #{analysisVersion}, 'REQUESTED'
)

mapper.select:
SELECT analysis_run_id, user_id, period_start, period_end, trade_count, journal_count,
       analysis_version, run_status, error_message, created_at
FROM analysis_runs
WHERE analysis_run_id = #{analysisRunId}
  AND user_id = #{userId}

mapper.update:
UPDATE analysis_runs
SET run_status = 'RUNNING'
WHERE analysis_run_id = #{analysisRunId}

UPDATE analysis_runs
SET run_status = 'SUCCESS', trade_count = #{tradeCount}, journal_count = #{journalCount}
WHERE analysis_run_id = #{analysisRunId}

UPDATE analysis_runs
SET run_status = 'FAILED', error_message = #{errorMessage}
WHERE analysis_run_id = #{analysisRunId}
